WITH normalized_modules AS (
  SELECT
    rd."project_id",
    upper(btrim(rd."module_key")) AS normalized_name,
    min(rd."created_at") AS created_at,
    max(rd."updated_at") AS updated_at,
    CASE
      WHEN bool_or(rd."state" = 'active') THEN 'active'
      ELSE 'archived'
    END AS status
  FROM "requirement_documents" rd
  WHERE btrim(rd."module_key") <> ''
  GROUP BY rd."project_id", upper(btrim(rd."module_key"))
),
ordered_modules AS (
  SELECT
    nm.*,
    row_number() OVER (PARTITION BY nm."project_id" ORDER BY nm."normalized_name") - 1 AS sort_order
  FROM normalized_modules nm
)
INSERT INTO "project_modules" (
  "project_id",
  "name",
  "description",
  "sort_order",
  "status",
  "created_at",
  "updated_at"
)
SELECT
  om."project_id",
  om."normalized_name",
  NULL,
  om."sort_order",
  om."status",
  om."created_at",
  om."updated_at"
FROM ordered_modules om;
--> statement-breakpoint
UPDATE "requirement_documents" rd
SET "module_id" = pm."id"
FROM "project_modules" pm
WHERE pm."project_id" = rd."project_id"
  AND pm."name" = upper(btrim(rd."module_key"));
--> statement-breakpoint
UPDATE "requirements" r
SET "module_id" = rd."module_id"
FROM "requirement_documents" rd
WHERE rd."id" = r."document_id"
  AND rd."module_id" IS NOT NULL;
--> statement-breakpoint
